package rustagent

import (
	"crypto/ed25519"
	"crypto/x509"
	"encoding/base64"
	"encoding/json"
	"os"
	"testing"
	"time"

	"localrmm/internal/enrollmentcrypto"
)

// This fixture is generated by the Rust enrollment_fixture example. It carries
// invented public keys and proofs only, never a private key or real enrollment.
func TestRustEnrollmentProofsAcceptedByGo(t *testing.T) {
	var fixture struct {
		Now             time.Time                         `json:"now"`
		Context         enrollmentcrypto.ChallengeContext `json:"context"`
		PublicKeyDER    string                            `json:"publicKeyDer"`
		Claim           json.RawMessage                   `json:"claim"`
		ClaimHash       string                            `json:"claimHash"`
		Status          json.RawMessage                   `json:"status"`
		Intent          enrollmentcrypto.Intent           `json:"intent"`
		IntentDigest    string                            `json:"intentDigest"`
		Activation      json.RawMessage                   `json:"activation"`
		CertificateHash string                            `json:"certificateHash"`
	}
	raw, err := os.ReadFile("enrollment-fixture.json")
	if err != nil {
		t.Fatal(err)
	}
	if err := json.Unmarshal(raw, &fixture); err != nil {
		t.Fatal(err)
	}
	claim, err := enrollmentcrypto.VerifyClaim(fixture.Claim, fixture.Context, fixture.Now)
	if err != nil {
		t.Fatal("Rust claim proof rejected:", err)
	}
	if claim.ClaimHash() != fixture.ClaimHash {
		t.Fatal("Rust and Go semantic claim digests differ")
	}
	keyDER, err := base64.RawStdEncoding.Strict().DecodeString(fixture.PublicKeyDER)
	if err != nil {
		t.Fatal(err)
	}
	status, err := enrollmentcrypto.VerifyStatus(fixture.Status, keyDER, fixture.Context, fixture.Now)
	if err != nil || status.Purpose() != "status" {
		t.Fatal("Rust status proof rejected:", err)
	}
	digest, err := enrollmentcrypto.IntentDigest(fixture.Intent)
	if err != nil || digest != fixture.IntentDigest {
		t.Fatal("Rust and Go issuance-intent digests differ", err)
	}
	var activation struct {
		RequestID string `json:"requestId"`
		Proof     string `json:"proof"`
	}
	if err := json.Unmarshal(fixture.Activation, &activation); err != nil {
		t.Fatal(err)
	}
	message, err := enrollmentcrypto.ActivationSigningMessage(fixture.Context, fixture.Intent, activation.RequestID, fixture.CertificateHash, fixture.Now)
	if err != nil {
		t.Fatal(err)
	}
	signature, err := base64.RawStdEncoding.Strict().DecodeString(activation.Proof)
	if err != nil {
		t.Fatal(err)
	}
	key, err := x509.ParsePKIXPublicKey(keyDER)
	if err != nil {
		t.Fatal(err)
	}
	publicKey, ok := key.(ed25519.PublicKey)
	if !ok || !ed25519.Verify(publicKey, message, signature) {
		t.Fatal("Rust activation possession signature rejected")
	}
	wrongContext := fixture.Context
	wrongContext.Origin = "https://different-manager.example"
	if _, err := enrollmentcrypto.VerifyClaim(fixture.Claim, wrongContext, fixture.Now); err == nil {
		t.Fatal("claim is not manager-origin-bound")
	}
	if _, err := enrollmentcrypto.VerifyStatus(fixture.Status, keyDER, wrongContext, fixture.Now); err == nil {
		t.Fatal("status is not manager-origin-bound")
	}
	message[0] ^= 1
	if ed25519.Verify(publicKey, message, signature) {
		t.Fatal("activation signature accepts a modified transcript")
	}
}
